function NASAObjectImage({object}:{object:SkyObject}) { const {data,loading,error}=useLoad(()=>api.images(object.name),[object.id]); const item=data?.items[0]; return <section className="object-image-section"><div><Eyebrow>NASA IMAGE LIBRARY Â· SEARCH RESULT</Eyebrow><h2>Related imagery</h2><p>Search results are matched by name; they are not verified SPHEREx observations.</p></div>{loading&&<div className="status"><span className="spinner"/> Searching NASAâ€™s image libraryâ€¦</div>}{error&&<p className="fine-print">Image search is unavailable. <Link to="/lab">Open Visualization Lab to retry</Link>.</p>}{item&&<figure><img src={item.previewUrl} alt={item.title} loading="lazy"/><figcaption><b>{item.title}</b><span>{item.center||'NASA'} {item.photographer?`Â· ${item.photographer}`:''} {item.dateCreated?`Â· ${item.dateCreated.slice(0,10)}`:''}</span><a href={item.manifestUrl} target="_blank" rel="noreferrer">Open asset and credit details <ExternalLink size={12}/></a></figcaption></figure>}</section> }function MissionPage() { const { data, loading, error } = useLoad(api.mission); return <><PageHeading eyebrow="MISSION CENTER Â· NASA SPHEREx" title="A new map of the cosmos." description="Meet the space telescope mapping the entire sky in more colors than ever before."/><Status loading={loading} error={error}/>{data && <><section className="mission-hero"><div className="mission-orbit"><div className="orbit-ring ring-one"/><div className="orbit-ring ring-two"/><div className="mission-core"><Orbit size={35}/></div><span className="orbit-dot dot-one"/><span className="orbit-dot dot-two"/></div><div className="mission-copy"><Badge tone="cyan">NASA ASTROPHYSICS MISSION</Badge><h2>{data.name}<br/><em>maps the whole sky.</em></h2><p>{data.subtitle}</p><div className="mission-specs"><span><b>102</b><small>SPECTRAL BANDS</small></span><span><b>0.75â€“5.0 <small>Î¼m</small></b><small>INFRARED RANGE</small></span><span><b>ALL-SKY</b><small>SURVEY DESIGN</small></span></div></div></section><div className="section-title-row"><div><Eyebrow>SCIENCE OBJECTIVES</Eyebrow><h2>Three questions. One sky.</h2></div><span className="section-index">01 â€” 03</span></div><div className="goals-list">{data.scienceGoals.map(goal => <div className="goal-row" key={goal.id}><span className={`goal-number ${goal.color}`}>{goal.icon}</span><div><h3>{goal.title}</h3><p>{goal.text}</p></div><Link to={goal.id === 'water' ? '/learn/cosmic-ices' : goal.id === 'inflation' ? '/learn/cosmic-inflation' : '/learn/galaxy-evolution'} aria-label={`Learn about ${goal.title}`}><ArrowUpRight/></Link></div>)}</div><section className="mission-bottom"><div><span className="micro-label">HOW SPHEREx WORKS</span><h3>One survey.<br/>A hundred shades of infrared.</h3><p>As the observatory scans the sky, its detectors and filters collect spectral information that helps scientists investigate galaxies, cosmic history, and molecules in our own galaxy.</p></div><div className="mission-band-art"><span>NEAR INFRARED</span><div className="spectrum-gradient"/><span>MID INFRARED</span><Link to="/explore/spectrum">Explore the bands <ArrowRight size={14}/></Link></div></section><section className="mission-timeline"><div><Eyebrow>MISSION TIMELINE</Eyebrow><h2>From launch to all-sky survey.</h2><p>{data.observationStrategy}</p><span className="micro-label">INSTRUMENT Â· {data.detectorAssemblies || 6} DETECTOR/FILTER ASSEMBLIES Â· 102 CHANNELS</span></div><ol>{data.timeline?.map(item=><li key={item.label}><span>{item.date}</span><div><b>{item.label}</b><p>{item.detail}</p><a href={item.sourceUrl} target="_blank" rel="noreferrer">Mission source <ExternalLink size={12}/></a></div></li>)}</ol></section><div className="source-list"><span className="micro-label">OFFICIAL MISSION SOURCES</span>{data.sources.slice(0,2).map(s => <a href={s.url} target="_blank" rel="noreferrer" key={s.id}>{s.name}<ExternalLink size={13}/></a>)}</div><p className="fine-print">Mission overview and science goals are educational summaries. SPHEREx observation products are not connected to this application.</p></>}</> }
